const text = String($json.text || "");
const today = String($json.today || new Date().toISOString().slice(0, 10));
const items = Array.isArray($json.items) ? $json.items : [];
const itemsList = items.map(i => i.date + " (" + (i.day_name || "") + "): shows " + (i.shown_hours ?? "unknown") + ", we suggested " + (i.proposed_hours ?? "nothing")).join("; ");
return { json: { text, today, items, items_list: itemsList } };

const ctx = $('Prepare Input').item.json;
const items = Array.isArray(ctx.items) ? ctx.items : [];
const allowed = new Set(items.map(i => String(i.date)));
const INTENTS = ["SET_CHANGES", "DECLINE", "UNCLEAR"];

let cand;
let parser;
if ($json.llm_error === true) {
  return { json: { intent: "UNCLEAR", changes: [], reason: "LLM_ERROR", parser: "LLM" } };
} else if ($json.output !== undefined) {
  cand = $json.output;
  parser = "LLM";
} else {
  return { json: { intent: "UNCLEAR", changes: [], reason: "NO_MATCH", parser: "LLM" } };
}

if (typeof cand === "string") {
  try { cand = JSON.parse(cand.replace(/^\s*```(?:json)?/i, "").replace(/```\s*$/, "")); } catch (e) { cand = null; }
}
const unclear = reason => ({ json: { intent: "UNCLEAR", changes: [], reason, parser } });
if (!cand || typeof cand !== "object") return unclear("NO_MATCH");

const intent = String(cand.intent || "").toUpperCase();
if (!INTENTS.includes(intent)) return unclear("NO_MATCH");
if (intent === "DECLINE") return { json: { intent: "DECLINE", changes: [], reason: null, parser } };
if (intent === "UNCLEAR") return unclear(cand.reason && ["NO_MATCH", "BAD_TIME", "BAD_DATE", "LLM_ERROR"].includes(cand.reason) ? cand.reason : "NO_MATCH");

const pad = n => String(n).padStart(2, "0");
function normHours(h) {
  const s = String(h ?? "").trim().toLowerCase().replace(/[–—]/g, "-").replace(/\s+/g, "");
  if (s === "closed") return "closed";
  if (s === "regular") return "regular";
  const parts = s.split(",");
  const outParts = [];
  for (const p of parts) {
    const mm = p.match(/^(\d{1,2})[:.](\d{2})-(\d{1,2})[:.](\d{2})$/);
    if (!mm) return null;
    const h1 = Number(mm[1]), m1 = Number(mm[2]), h2 = Number(mm[3]), m2 = Number(mm[4]);
    if (h1 > 24 || h2 > 24 || m1 > 59 || m2 > 59) return null;
    if ((h1 === 24 && m1 > 0) || (h2 === 24 && m2 > 0)) return null;
    if (h1 * 60 + m1 >= h2 * 60 + m2) return null;
    outParts.push(pad(h1) + ":" + pad(m1) + "-" + pad(h2) + ":" + pad(m2));
  }
  return outParts.length ? outParts.join(",") : null;
}

const raw = Array.isArray(cand.changes) ? cand.changes : [];
const byDate = {};
let badDate = false, badTime = false;
for (const c of raw) {
  const date = String(c && c.date || "").trim();
  if (!allowed.has(date)) { badDate = true; continue; }
  const hours = normHours(c.hours);
  if (hours === null) { badTime = true; continue; }
  byDate[date] = hours;
}
if (badDate) return unclear("BAD_DATE");
if (badTime) return unclear("BAD_TIME");
const changes = Object.keys(byDate).sort().map(d => ({ date: d, hours: byDate[d] }));
if (changes.length === 0) return unclear("NO_MATCH");
return { json: { intent: "SET_CHANGES", changes, reason: null, parser } };
